  "questions": [
    {
      "question": "Quel est l'un des principaux caractéristiques d'une blockchain ?",
      "options": [
        "Centralisée",
        "Modifiable",
        "Distribuée",
        "Fragile"
      ],
      "answer": 2,
      "explanation": "Une blockchain est distribuée, ce qui signifie que le registre est répliqué sur plusieurs nœuds."
    },
    {
      "question": "Comment appelle-t-on les entités qui participent à la validation des transactions dans une blockchain ?",
      "options": [
        "Les mineurs",
        "Les détenteurs",
        "Les validateurs",
        "Les utilisateurs finaux"
      ],
      "answer": 2,
      "explanation": "Les validateurs sont responsables de la validation des transactions dans une blockchain."
    },
    {
      "question": "Quel type de blockchain est accessible à tous et permet à n'importe quel nœud de valider les transactions ?",
      "options": [
        "Blockchain privée",
        "Blockchain hybride",
        "Blockchain consortium",
        "Blockchain publique"
      ],
      "answer": 3,
      "explanation": "Une blockchain publique est ouverte à tous et permet à tout nœud de valider les transactions."
    }
  ]
}

