messages.content:
{
  "questions": [
    {
      "question": "Quel est l'objectif du contrôle quantitatif et qualitatif lors de la réception d'un produit ?",
      "options": [
        "D'identifier les produits incompatibles.",
        "De vérifier la quantité et la qualité des produits avant leur mise en stock.",
        "De déterminer la date de péremption des produits.",
        "De consigner les écarts sur le bon de réception."
      ],
      "answer": 1,
      "explanation": "Le contrôle quantitatif et qualitatif vise à vérifier la quantité et la qualité des produits avant leur mise en stock, comme indiqué dans le paragraphe « La réception »."
    },
    {
      "question": "Quelle règle est appliquée aux produits ayant une date de péremption ?",
      "options": [
        "Le stockage doit respecter les prescriptions du fournisseur.",
        "La rotation par ordre d'arrivée s'applique à ces produits.",
        "Les produits incompatibles doivent être séparés physiquement.",
        "L'inventaire tournant permet de vérifier la fiabilité du stock."
      ],
      "answer": 1,
      "explanation": "Le paragraphe « La rotation » mentionne que « la règle du premier entré, premier sorti s'applique aux produits soumis à une date de péremption »."
    },
    {
      "question": "En quelle situation l'inventaire tournant est-il le plus approprié ?",
      "options": [
        "Lorsqu'une quantité importante de produits doit être reçue.",
        "Lorsqu'il faut déterminer la date de péremption des produits.",
        "Lorsque l'activité doit être maintenue sans interruption.",
        "Lorsque les conditions de stockage sont difficiles à respecter."
      ],
      "answer": 2,
      "explanation": "L'inventaire tournant est décrit comme permettant de vérifier la fiabilité du stock « sans interrompre l’activité » dans le paragraphe « L’inventaire »."
    }
  ]
}

