messages.content:
{
  "questions": [
    {
      "question": "Quel est l'âge minimum requis pour devenir agent de sécurité selon la Loi N° 27.06 ?",
      "options": [
        "18 ans",
        "21 ans",
        "25 ans",
        "30 ans"
      ],
      "answer": 1,
      "explanation": "La loi stipule qu'un agent de sécurité doit être âgé d'au moins 21 ans. (Art. 13-20)"
    },
    {
      "question": "La Loi N° 27.06 régit toutes les activités suivantes :",
      "options": [
        "Seulement la surveillance de biens immobiliers",
        "Le transport de fonds et la protection des personnes uniquement",
        "La surveillance, le gardiennage, le transport de fonds et la protection des personnes",
        "L'installation et la maintenance de systèmes de sécurité uniquement"
      ],
      "answer": 2,
      "explanation": "La loi régit notamment la surveillance et le gardiennage de biens, le transport de fonds, la protection des personnes et l'installation de systèmes de sécurité. (Art. 1-3)"
    },
    {
      "question": "Un agent de sécurité doit obligatoirement souscrire à quel type d'assurance ?",
      "options": [
        "Assurance maladie",
        "Assurance habitation",
        "Assurance responsabilité civile professionnelle",
        "Assurance accident du travail"
      ],
      "answer": 2,
      "explanation": "La loi impose aux entreprises de sécurité de faire souscrire à leurs agents une assurance responsabilité civile professionnelle. (Art. 4-12)"
    }
  ]
}

