    {
      "question": "Quel est l'objectif principal du projet de Loi N° 032.26 ?",
      "options": [
        "Amender l'article 193 du Code du Travail concernant les licenciements abusifs.",
        "Réguler le travail des agents de sécurité privée en adaptant les règles du temps de travail.",
        "Créer un nouveau système d'assurance maladie pour les travailleurs du secteur privé.",
        "Limiter le nombre d'agents de sécurité privés autorisés au Maroc."
      ],
      "answer": 1,
      "explanation": "Le projet de loi vise à amender l'article 193 du Code du Travail concernant l'aménagement du temps de travail des agents de sécurité privée. (Contexte)"
    },
    {
      "question": "Quelles modifications sont envisagées pour les périodes d'astreinte ?",
      "options": [
        "Abolition totale des périodes d'astreinte.",
        "Augmentation du salaire pendant les périodes d'astreinte.",
        "Clarification du statut des périodes d'astreinte par rapport au temps de travail effectif.",
        "Introduction d'un repos obligatoire de 24 heures après chaque période d'astreinte."
      ],
      "answer": 2,
      "explanation": "Le projet de loi prévoit de clarifier le statut des périodes d'astreinte par rapport au temps de travail effectif. (Contexte)"
    },
    {
      "question": "Si un agent de sécurité privée travaille la nuit, quel type de modification est envisagé ?",
      "options": [
        "Réduction de 20% de son salaire.",
        "Majoration spécifique pour les agents travaillant la nuit.",
        "Obligation de faire une pause de 1 heure toutes les 4 heures.",
        "Autorisation de travailler jusqu'à 16 heures consécutives."
      ],
      "answer": 1,
      "explanation": "Le projet de loi envisage une majoration spécifique pour les agents de sécurité travaillant la nuit. (Contexte)"
    }
  ]
}

