      "question": "Quel est l'objectif principal du contrôle d'accès ?",
      "options": [
        "Sécuriser les communications internes.",
        "Gérer le flux de marchandises entre les fournisseurs.",
        "Vérifier l'identité des personnes entrant sur le site.",
        "Optimiser la circulation du personnel."
      ],
      "answer": 2,
      "explanation": "Le contrôle d'accès vise principalement à vérifier l'identité des personnes qui entrent sur le site."
    },
    {
      "question": "À quel niveau de contrôle les inspections du coffre sont-elles obligatoires ?",
      "options": [
        "Niveau 1 — Entrée piétonne",
        "Niveau 2 — Entrée véhicule",
        "Niveau 3 — Zone sensible",
        "Niveau 4 — Accès restreint"
      ],
      "answer": 1,
      "explanation": "Le niveau de contrôle « Entrée véhicule » prévoit une inspection du coffre."
    },
    {
      "question": "Quelle action doit un agent accomplir en cas d'anomalie lors d'une ronde de surveillance ?",
      "options": [
        "Continuer la ronde et signaler l'anomalie au poste central à la fin.",
        "Stopper la ronde, alerter le poste central et consigner l'anomalie dans un registre.",
        "Essayer de résoudre l'anomalie seul avant de contacter le poste central.",
        "Ignorer l'anomalie si elle semble peu grave."
      ],
      "answer": 1,
      "explanation": "En cas d'anomalie, l'agent doit stopper la ronde, alerter le poste central et consigner l'anomalie dans un registre."
    }
  ]
}

