messages.content:
{
  "questions": [
    {
      "question": "Quelle est la principale fonction de l'ISO 45001 ?",
      "options": [
        "Définir les normes d'hygiène dans les bâtiments industriels.",
        "Fournir un cadre pour gérer les risques liés à la santé et à la sécurité au travail.",
        "Mettre en place des formations obligatoires sur les machines dangereuses.",
        "Réguler l'utilisation des EPI (Equipements de Protection Individuelle) dans les entreprises."
      ],
      "answer": 1,
      "explanation": "L'ISO 45001 vise à fournir un cadre pour gérer les risques en matière de santé et sécurité au travail ."
    },
    {
      "question": "Selon la norme ISO 45001, quel élément est considéré comme important dans le contexte de l'organisme ?",
      "options": [
        "Le nombre d'accidents du travail survenus l'année dernière.",
        "L'âge moyen des employés travaillant dans l'entreprise.",
        "Les enjeux internes et externes qui peuvent affecter la santé et la sécurité au travail.",
        "La taille de la zone dangereuse autour des machines."
      ],
      "answer": 2,
      "explanation": "Le contexte de l'organisme comprend les enjeux internes et externes qui peuvent affecter la santé et la sécurité au travail ."
    },
    {
      "question": "Si une entreprise souhaite s'engager dans une démarche d'amélioration continue en matière de SST selon la norme ISO 45001, quel élément devrait-elle mettre en place ?",
      "options": [
        "Une formation obligatoire sur les premiers secours pour tous les employés.",
        "Un système de surveillance des machines à l'aide de caméras de sécurité.",
        "Des processus d'évaluation des performances pour mesurer l'efficacité du système de management de la santé et de la sécurité au travail .",
        "La mise en place d'un plan de communication interne sur les risques liés aux produits chimiques."
      ],
      "answer": 2,
      "explanation": "L'ISO 45001 encourage la mise en place de processus d'évaluation des performances pour mesurer l'efficacité du système de management de la santé et de la sécurité au travail ."
    }
  ]
}

