  "questions": [
    {
      "question": "Quel est l'objectif principal du lecture des codes défaut lors d'un diagnostic électronique ?",
      "options": [
        "Identifier immédiatement la pièce défectueuse.",
        "Déterminer le type de liquide à remplacer dans le système.",
        "Relever les symptômes présents et les consigner sur l'ordre de réparation.",
        "Vérifier la pression des pneus avant toute intervention."
      ],
      "answer": 2,
      "explanation": "L'objectif est de relever les symptômes présents et les consignes sur l'ordre de réparation, comme indiqué dans le paragraphe 1."
    },
